{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2137-12-25 01:30:00",
      "speaker": "Doctor",
      "text": "Good morning. I’m Dr. Lee. You were brought in with severe abdominal pain, fever, and diarrhea. Can you tell me more about what happened?"
    },
    {
      "turn_number": 2,
      "time": "2137-12-25 01:32:00",
      "speaker": "Patient",
      "text": "Yes, I’ve had watery diarrhea all day, uncountable really, and crampy pain—like 8 or 9 out of 10. It started suddenly, and I had a fever of 102.5. It feels like food poisoning."
    },
    {
      "turn_number": 3,
      "time": "2137-12-25 01:34:00",
      "speaker": "Doctor",
      "text": "I see. Any blood in the stool? Travel? Or unusual foods?"
    },
    {
      "turn_number": 4,
      "time": "2137-12-25 01:35:00",
      "speaker": "Patient",
      "text": "No blood, no travel. I didn’t eat anything strange. But my cat has been sick—low energy, dry nose. Could that matter?"
    },
    {
      "turn_number": 5,
      "time": "2137-12-25 01:37:00",
      "speaker": "Doctor",
      "text": "Possibly, though it’s more likely a viral infection. We’ll run stool tests to check for infections. Your vitals were high in the ER—fever and elevated heart rate—but you’re more stable now."
    },
    {
      "turn_number": 6,
      "time": "2137-12-25 01:39:00",
      "speaker": "Patient",
      "text": "I’ve had nausea for months, especially after eating. It got worse after my last hospital stay."
    },
    {
      "turn_number": 7,
      "time": "2137-12-25 01:41:00",
      "speaker": "Doctor",
      "text": "Yes, your last admission was for nausea and kidney issues. We’ll keep an eye on your kidneys. For now, we’re giving IV fluids and monitoring."
    },
    {
      "turn_number": 8,
      "time": "2137-12-25 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your fever has gone down, and the diarrhea stopped. That’s a good sign. But you’re still not eating much, right?"
    },
    {
      "turn_number": 9,
      "time": "2137-12-25 08:02:00",
      "speaker": "Patient",
      "text": "No, I tried clear liquids, but I feel full fast and nauseous. Same as before."
    },
    {
      "turn_number": 10,
      "time": "2137-12-25 08:04:00",
      "speaker": "Doctor",
      "text": "We’re concerned about gastroparesis—delayed stomach emptying—especially with your diabetes. We’ll consult GI and may do a gastric emptying study."
    },
    {
      "turn_number": 11,
      "time": "2137-12-25 08:06:00",
      "speaker": "Patient",
      "text": "What causes that?"
    },
    {
      "turn_number": 12,
      "time": "2137-12-25 08:08:00",
      "speaker": "Doctor",
      "text": "Diabetes can damage nerves that control the stomach. That’s likely what’s happening here. We’ll confirm with a test."
    },
    {
      "turn_number": 13,
      "time": "2137-12-26 09:00:00",
      "speaker": "Doctor",
      "text": "The CT scan came back—no appendicitis, no blockage. Your abdomen looks clear. That supports the idea of a functional issue like gastroparesis."
    },
    {
      "turn_number": 14,
      "time": "2137-12-26 09:02:00",
      "speaker": "Patient",
      "text": "So no infection?"
    },
    {
      "turn_number": 15,
      "time": "2137-12-26 09:04:00",
      "speaker": "Doctor",
      "text": "Stool tests were negative for C. diff, parasites, and common bacteria. No sign of infection. The fever and diarrhea were likely a brief viral episode."
    },
    {
      "turn_number": 16,
      "time": "2137-12-26 09:06:00",
      "speaker": "Patient",
      "text": "But the nausea and fullness are still here."
    },
    {
      "turn_number": 17,
      "time": "2137-12-26 09:08:00",
      "speaker": "Doctor",
      "text": "Exactly. That’s why we’re moving forward with the gastric emptying study. It will show how fast your stomach empties food."
    },
    {
      "turn_number": 18,
      "time": "2137-12-27 10:00:00",
      "speaker": "Doctor",
      "text": "The gastric emptying study is back. It shows delayed emptying—only 61% emptied at 2 hours, and 39% was still in your stomach at 4 hours. That confirms gastroparesis."
    },
    {
      "turn_number": 19,
      "time": "2137-12-27 10:02:00",
      "speaker": "Patient",
      "text": "So that’s why I feel so full and nauseous?"
    },
    {
      "turn_number": 20,
      "time": "2137-12-27 10:04:00",
      "speaker": "Doctor",
      "text": "Yes. The stomach isn’t moving food into the intestines properly. We’ll start high-dose Zofran before meals to help with nausea and improve emptying."
    },
    {
      "turn_number": 21,
      "time": "2137-12-27 10:06:00",
      "speaker": "Patient",
      "text": "Will I ever eat normally again?"
    },
    {
      "turn_number": 22,
      "time": "2137-12-27 10:08:00",
      "speaker": "Doctor",
      "text": "You’ll need to make some changes—smaller, more frequent meals, low-fat, low-fiber, and lactose-free. We’ll give you diet instructions before discharge."
    },
    {
      "turn_number": 23,
      "time": "2137-12-27 14:00:00",
      "speaker": "Doctor",
      "text": "We’ve switched you from omeprazole to pantoprazole. It’s similar but may cause less nausea."
    },
    {
      "turn_number": 24,
      "time": "2137-12-27 14:02:00",
      "speaker": "Patient",
      "text": "Okay. And my diabetes meds?"
    },
    {
      "turn_number": 25,
      "time": "2137-12-27 14:04:00",
      "speaker": "Doctor",
      "text": "We’ve held your glyburide because you’re not eating well. We’re using insulin shots to manage your blood sugar safely."
    },
    {
      "turn_number": 26,
      "time": "2137-12-28 08:00:00",
      "speaker": "Doctor",
      "text": "How are you feeling? Any nausea?"
    },
    {
      "turn_number": 27,
      "time": "2137-12-28 08:02:00",
      "speaker": "Patient",
      "text": "Still nauseous, but I tried some toast. It stayed down."
    },
    {
      "turn_number": 28,
      "time": "2137-12-28 08:04:00",
      "speaker": "Doctor",
      "text": "That’s progress. We’ll keep advancing your diet slowly. Also, you’ve been constipated the last few days."
    },
    {
      "turn_number": 29,
      "time": "2137-12-28 08:06:00",
      "speaker": "Patient",
      "text": "I haven’t had a bowel movement in four days."
    },
    {
      "turn_number": 30,
      "time": "2137-12-28 08:08:00",
      "speaker": "Doctor",
      "text": "We’ll give a Dulcolax suppository and docusate to help. Constipation can happen with gastroparesis and pain meds."
    },
    {
      "turn_number": 31,
      "time": "2137-12-29 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—the constipation resolved with the enema. You’re passing stool normally now."
    },
    {
      "turn_number": 32,
      "time": "2137-12-29 07:02:00",
      "speaker": "Patient",
      "text": "I feel better. Can I try more food?"
    },
    {
      "turn_number": 33,
      "time": "2137-12-29 07:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll try a full liquid diet today, then soft foods tomorrow. The goal is to get you on a regular diet before discharge."
    },
    {
      "turn_number": 34,
      "time": "2137-12-30 08:00:00",
      "speaker": "Doctor",
      "text": "You tolerated the soft diet well. No nausea or vomiting. That’s a big step."
    },
    {
      "turn_number": 35,
      "time": "2137-12-30 08:02:00",
      "speaker": "Patient",
      "text": "I’m still tired, but I’m glad I can eat."
    },
    {
      "turn_number": 36,
      "time": "2137-12-30 08:04:00",
      "speaker": "Doctor",
      "text": "Your kidney function is stable—creatinine 1.1, near your baseline. That’s good. We’ll keep you on IV fluids until you’re drinking enough."
    },
    {
      "turn_number": 37,
      "time": "2137-12-30 14:00:00",
      "speaker": "Doctor",
      "text": "We reviewed your blood pressure meds. You’ve been missing labetalol doses because of low heart rate."
    },
    {
      "turn_number": 38,
      "time": "2137-12-30 14:02:00",
      "speaker": "Patient",
      "text": "I feel dizzy and tired when I take it."
    },
    {
      "turn_number": 39,
      "time": "2137-12-30 14:04:00",
      "speaker": "Doctor",
      "text": "We’re discontinuing labetalol. Your blood pressure is well-controlled on lisinopril, amlodipine, and spironolactone."
    },
    {
      "turn_number": 40,
      "time": "2137-12-31 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve been on a full diet for a day with no issues. We’re planning for discharge in a couple of days if this continues."
    },
    {
      "turn_number": 41,
      "time": "2137-12-31 09:02:00",
      "speaker": "Patient",
      "text": "What meds will I go home with?"
    },
    {
      "turn_number": 42,
      "time": "2137-12-31 09:04:00",
      "speaker": "Doctor",
      "text": "You’ll take lisinopril, amlodipine, spironolactone for blood pressure, simvastatin for cholesterol, and pantoprazole for stomach protection."
    },
    {
      "turn_number": 43,
      "time": "2137-12-31 09:06:00",
      "speaker": "Doctor",
      "text": "For gastroparesis, you’ll take ondansetron before meals. And docusate if constipated."
    },
    {
      "turn_number": 44,
      "time": "2137-12-31 09:08:00",
      "speaker": "Patient",
      "text": "No more glyburide?"
    },
    {
      "turn_number": 45,
      "time": "2137-12-31 09:10:00",
      "speaker": "Doctor",
      "text": "Not for now. Your PCP will decide when to restart it based on your eating and blood sugars."
    },
    {
      "turn_number": 46,
      "time": "2138-01-01 08:00:00",
      "speaker": "Doctor",
      "text": "Last night you slept well. No nausea, and you finished your meals. We’re on track for discharge tomorrow."
    },
    {
      "turn_number": 47,
      "time": "2138-01-01 08:02:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. But what if the nausea comes back?"
    },
    {
      "turn_number": 48,
      "time": "2138-01-01 08:04:00",
      "speaker": "Doctor",
      "text": "Take the ondansetron before meals. Stick to small, low-fat meals. Call your doctor if you have severe pain, fever, or can’t keep food down."
    },
    {
      "turn_number": 49,
      "time": "2138-01-01 08:06:00",
      "speaker": "Patient",
      "text": "And my follow-up?"
    },
    {
      "turn_number": 50,
      "time": "2138-01-01 08:08:00",
      "speaker": "Doctor",
      "text": "See your primary care doctor soon. Keep your GI appointment. They’ll monitor your gastroparesis."
    },
    {
      "turn_number": 51,
      "time": "2138-01-01 14:00:00",
      "speaker": "Doctor",
      "text": "We’ve updated your discharge meds. You’ll get a 30-day supply of pantoprazole and 60 ondansetron tablets."
    },
    {
      "turn_number": 52,
      "time": "2138-01-01 14:02:00",
      "speaker": "Patient",
      "text": "And the inhaler?"
    },
    {
      "turn_number": 53,
      "time": "2138-01-01 14:04:00",
      "speaker": "Doctor",
      "text": "Yes, keep using your Flovent for asthma. It’s unchanged."
    },
    {
      "turn_number": 54,
      "time": "2138-01-01 15:00:00",
      "speaker": "Doctor",
      "text": "One more thing—your last EGD showed a hiatal hernia and mild gastritis. The polyps were likely from long-term PPI use."
    },
    {
      "turn_number": 55,
      "time": "2138-01-01 15:02:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 56,
      "time": "2138-01-01 15:04:00",
      "speaker": "Doctor",
      "text": "No, the polyps are benign. But we’ll monitor them. The hernia may contribute to reflux, so stay upright after eating."
    },
    {
      "turn_number": 57,
      "time": "2138-01-02 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge. Your condition has improved significantly."
    },
    {
      "turn_number": 58,
      "time": "2138-01-02 07:02:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better."
    },
    {
      "turn_number": 59,
      "time": "2138-01-02 07:04:00",
      "speaker": "Doctor",
      "text": "Remember: take ondansetron before meals, eat small lactose-free meals, and don’t restart labetalol unless your doctor says so."
    },
    {
      "turn_number": 60,
      "time": "2138-01-02 07:06:00",
      "speaker": "Patient",
      "text": "Got it. And call if I get worse."
    },
    {
      "turn_number": 61,
      "time": "2138-01-02 07:08:00",
      "speaker": "Doctor",
      "text": "Exactly. Take care, and we’ll see you in follow-up."
    },
    {
      "turn_number": 62,
      "time": "2138-01-02 07:10:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 63,
      "time": "2138-01-02 08:00:00",
      "speaker": "Doctor",
      "text": "Nurse will go over your diet and meds one more time before you leave."
    },
    {
      "turn_number": 64,
      "time": "2138-01-02 08:02:00",
      "speaker": "Patient",
      "text": "Okay, I’ll listen carefully."
    },
    {
      "turn_number": 65,
      "time": "2138-01-02 09:00:00",
      "speaker": "Doctor",
      "text": "All set. You’re doing well. Discharge paperwork is ready."
    },
    {
      "turn_number": 66,
      "time": "2138-01-02 09:02:00",
      "speaker": "Patient",
      "text": "I’m ready to go home now."
    },
    {
      "turn_number": 67,
      "time": "2138-01-02 09:04:00",
      "speaker": "Doctor",
      "text": "Take it easy. Rest, follow the diet, and keep your appointments."
    },
    {
      "turn_number": 68,
      "time": "2138-01-02 09:06:00",
      "speaker": "Patient",
      "text": "I will. Thank you for everything."
    },
    {
      "turn_number": 69,
      "time": "2138-01-02 09:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Feel better soon."
    },
    {
      "turn_number": 70,
      "time": "2138-01-02 09:10:00",
      "speaker": "Patient",
      "text": "I already feel better than I have in weeks."
    },
    {
      "turn_number": 71,
      "time": "2138-01-02 09:12:00",
      "speaker": "Doctor",
      "text": "That’s great to hear. We’re glad we could help."
    },
    {
      "turn_number": 72,
      "time": "2138-01-02 09:14:00",
      "speaker": "Patient",
      "text": "Will I need another test later?"
    },
    {
      "turn_number": 73,
      "time": "2138-01-02 09:16:00",
      "speaker": "Doctor",
      "text": "Not right now. Your GI doctor will decide if further monitoring is needed."
    },
    {
      "turn_number": 74,
      "time": "2138-01-02 09:18:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense."
    },
    {
      "turn_number": 75,
      "time": "2138-01-02 09:20:00",
      "speaker": "Doctor",
      "text": "Just keep track of your symptoms and report any changes."
    },
    {
      "turn_number": 76,
      "time": "2138-01-02 09:22:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 77,
      "time": "2138-01-02 09:24:00",
      "speaker": "Doctor",
      "text": "Take care. Safe trip home."
    },
    {
      "turn_number": 78,
      "time": "2138-01-02 09:26:00",
      "speaker": "Patient",
      "text": "I will. Bye."
    },
    {
      "turn_number": 79,
      "time": "2138-01-02 09:28:00",
      "speaker": "Doctor",
      "text": "Goodbye."
    },
    {
      "turn_number": 80,
      "time": "2138-01-02 09:30:00",
      "speaker": "Patient",
      "text": "I’ll follow up as told."
    },
    {
      "turn_number": 81,
      "time": "2138-01-02 09:32:00",
      "speaker": "Doctor",
      "text": "Perfect. We’re here if you need us."
    },
    {
      "turn_number": 82,
      "time": "2138-01-02 09:34:00",
      "speaker": "Patient",
      "text": "I appreciate that."
    },
    {
      "turn_number": 83,
      "time": "2138-01-02 09:36:00",
      "speaker": "Doctor",
      "text": "Have a good day."
    },
    {
      "turn_number": 84,
      "time": "2138-01-02 09:38:00",
      "speaker": "Patient",
      "text": "You too."
    },
    {
      "turn_number": 85,
      "time": "2138-01-02 09:40:00",
      "speaker": "Doctor",
      "text": "Take care."
    }
  ],
  "summary": {
    "admission_start": "2137-12-25 01:30:00",
    "admission_end": "2138-01-02 11:29:00",
    "summary_paragraph": "A woman with type 2 diabetes and a recent hospitalization for nausea and acute kidney injury was readmitted with fever, severe crampy abdominal pain, and watery diarrhea. The infectious workup was negative, and symptoms resolved quickly, but persistent nausea and inability to tolerate food raised concern for gastroparesis. A gastric emptying study confirmed delayed gastric emptying. She was managed with high-dose ondansetron, dietary modifications, and discontinuation of labetalol due to bradycardia. She advanced to a full diet, had constipation resolved with laxatives, and was discharged home in improved condition with a lactose-free diet and follow-up plan.",
    "problems": [
      "Diabetes with neurological manifestations, type II or unspecified type, not stated as uncontrolled",
      "Chronic diastolic heart failure",
      "Gastroparesis",
      "Other constipation",
      "Congestive heart failure, unspecified",
      "Other chronic pulmonary heart diseases",
      "Chronic kidney disease, unspecified",
      "Hypertensive chronic kidney disease, benign, with chronic kidney disease stage I through stage IV, or unspecified",
      "Other and unspecified hyperlipidemia",
      "Morbid obesity",
      "Migraine, unspecified, without mention of intractable migraine without mention of status migrainosus",
      "Asthma, unspecified type, unspecified",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Other acquired absence of organ",
      "Acquired absence of both cervix and uterus"
    ]
  }
}
